standard_solution_code:
class Solution:

	def findElement(self, a, n, x, ranges, k):
		for i in range(k - 1, -1, -1):
			if x > ranges[i][0] and x <= ranges[i][1]:
				x -= 1
			elif x == ranges[i][0]:
				x = ranges[i][1]
		return a[x]
